async () => {
  const data = await connecta.call("controlled.records", { count: 180 });
  const rows = Array.isArray(data) ? data : (data.records || data.items || data.result);
  if (!Array.isArray(rows)) throw new Error("Unexpected records shape");
  const out = {};
  for (const row of rows) {
    const g = row.group;
    if (!out[g]) out[g] = { count: 0, scoreSum: 0 };
    out[g].count += 1;
    out[g].scoreSum += row.score;
  }
  return out;
}

